/* ============================================================
   SunshineAirlines 自拟练习库（配合湖北样题训练）
   说明：湖北样题使用的官方数据库脚本 MSSQL-Session1.sql 不在资料包中。
         本脚本是按题目文字描述自拟的结构与数据，仅供练习，
         表名、字段名与官方脚本不一定相同。
   使用：在 SSMS 中打开，F5 执行。会删除并重建 Session1Practice 库。
         航班日期以执行当天为基准生成（过去 60 天到未来 30 天）。
   ============================================================ */
USE master;
GO
IF DB_ID(N'Session1Practice') IS NOT NULL
BEGIN
    ALTER DATABASE Session1Practice SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE Session1Practice;
END
GO
CREATE DATABASE Session1Practice;
GO
USE Session1Practice;
GO
CREATE TABLE Role (
    RoleId   INT          NOT NULL CONSTRAINT PK_Role PRIMARY KEY,
    RoleName NVARCHAR(20) NOT NULL
);
CREATE TABLE Users (
    UserId      INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Users PRIMARY KEY,
    Email       NVARCHAR(100) NOT NULL CONSTRAINT UQ_Users_Email UNIQUE,
    Password    NVARCHAR(50)  NOT NULL,
    FirstName   NVARCHAR(50)  NOT NULL,
    LastName    NVARCHAR(50)  NOT NULL,
    Gender      CHAR(1)       NOT NULL CONSTRAINT CK_Users_Gender CHECK (Gender IN ('M','F')),
    DateOfBirth DATE          NULL,
    Phone       NVARCHAR(20)  NULL,
    Photo       NVARCHAR(100) NULL,
    Address     NVARCHAR(200) NULL,
    RoleId      INT           NOT NULL CONSTRAINT FK_Users_Role REFERENCES Role(RoleId)
);
CREATE TABLE City (
    CityCode NVARCHAR(10) NOT NULL CONSTRAINT PK_City PRIMARY KEY,
    CityName NVARCHAR(50) NOT NULL
);
CREATE TABLE Airport (
    IATACode NVARCHAR(3)   NOT NULL CONSTRAINT PK_Airport PRIMARY KEY,
    Name     NVARCHAR(100) NOT NULL,
    CityCode NVARCHAR(10)  NOT NULL CONSTRAINT FK_Airport_City REFERENCES City(CityCode)
);
CREATE TABLE Aircraft (
    AircraftId    INT          NOT NULL CONSTRAINT PK_Aircraft PRIMARY KEY,
    Name          NVARCHAR(50) NOT NULL,
    EconomySeats  INT NOT NULL,
    BusinessSeats INT NOT NULL,
    FirstSeats    INT NOT NULL
);
CREATE TABLE CabinType (
    CabinTypeId   INT          NOT NULL CONSTRAINT PK_CabinType PRIMARY KEY,
    CabinTypeName NVARCHAR(20) NOT NULL
);
CREATE TABLE Schedule (
    ScheduleId         INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Schedule PRIMARY KEY,
    FlightNumber       NVARCHAR(10)  NOT NULL,
    DepartureAirport   NVARCHAR(3)   NOT NULL CONSTRAINT FK_Schedule_Dep REFERENCES Airport(IATACode),
    ArrivalAirport     NVARCHAR(3)   NOT NULL CONSTRAINT FK_Schedule_Arr REFERENCES Airport(IATACode),
    AircraftId         INT           NOT NULL CONSTRAINT FK_Schedule_Aircraft REFERENCES Aircraft(AircraftId),
    DepartureTime      DATETIME      NOT NULL,
    FlightMinutes      INT           NOT NULL,
    Gate               NVARCHAR(5)   NULL,
    EconomyPrice       DECIMAL(10,2) NOT NULL,
    Status             NVARCHAR(20)  NOT NULL CONSTRAINT DF_Schedule_Status DEFAULT N'Confirmed'  -- Confirmed / Canceled
);
CREATE TABLE FlightStatus (
    ScheduleId    INT      NOT NULL CONSTRAINT PK_FlightStatus PRIMARY KEY CONSTRAINT FK_FlightStatus_Schedule REFERENCES Schedule(ScheduleId),
    ActualArrival DATETIME NOT NULL
);
CREATE TABLE Ticket (
    TicketId    INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Ticket PRIMARY KEY,
    ScheduleId  INT           NOT NULL CONSTRAINT FK_Ticket_Schedule REFERENCES Schedule(ScheduleId),
    CabinTypeId INT           NOT NULL CONSTRAINT FK_Ticket_Cabin REFERENCES CabinType(CabinTypeId),
    UserId      INT           NOT NULL CONSTRAINT FK_Ticket_Users REFERENCES Users(UserId),
    Price       DECIMAL(10,2) NOT NULL,
    SeatNo      NVARCHAR(5)   NULL,       -- 仅头等舱选座后有值，如 2A
    BookedAt    DATETIME      NOT NULL
);
CREATE TABLE LoginRecord (
    RecordId   INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_LoginRecord PRIMARY KEY,
    UserId     INT      NOT NULL CONSTRAINT FK_LoginRecord_Users REFERENCES Users(UserId),
    LoginTime  DATETIME NOT NULL,
    LogoutTime DATETIME NULL
);
CREATE TABLE MileagePoints (
    PointId  INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_MileagePoints PRIMARY KEY,
    UserId   INT          NOT NULL CONSTRAINT FK_Mileage_Users REFERENCES Users(UserId),
    Points   INT          NOT NULL,
    Reason   NVARCHAR(50) NOT NULL,
    PointsAt DATETIME     NOT NULL
);
GO

-- 初始密码规则（湖北样题描述）：邮箱 @ 前 6 位字符，不足 6 位取全部
GO
-- 航班：以执行当天为基准，过去 60 天到未来 30 天，每天若干班
DECLARE @today DATE = CAST(GETDATE() AS DATE);

-- 已起飞的非取消航班记录实际到达时间（随机早到 / 晚到）
SELECT ScheduleId, DATEADD(MINUTE, FlightMinutes + (ScheduleId * 37 % 71) - 25, DepartureTime)
FROM Schedule WHERE DepartureTime < GETDATE() AND Status = N'Confirmed';

-- 机票：客户 4–6 随机购票；经济舱价格为基准，商务舱 ×1.5，头等舱 ×2
SELECT s.ScheduleId, c.CabinTypeId, 4 + (s.ScheduleId + c.CabinTypeId) % 3,
       s.EconomyPrice * CASE c.CabinTypeId WHEN 1 THEN 1 WHEN 2 THEN 1.5 ELSE 2 END,
       CASE WHEN c.CabinTypeId = 3 AND s.ScheduleId % 2 = 0 THEN CAST(1 + s.ScheduleId % 2 AS NVARCHAR(2)) + N'A' END,
       DATEADD(DAY, -3, s.DepartureTime)
FROM Schedule s CROSS JOIN CabinType c
CROSS JOIN (VALUES (1),(2),(3),(4),(5),(6),(7),(8)) n(k)
WHERE s.Status = N'Confirmed'
  AND n.k <= CASE c.CabinTypeId WHEN 1 THEN 2 + s.ScheduleId % 7 WHEN 2 THEN s.ScheduleId % 3 ELSE s.ScheduleId % 2 END;

-- 让部分未来航班经济舱接近售罄（用于“余票 ≤ 3 红色显示”）
SELECT s.ScheduleId, 1, 4, s.EconomyPrice, NULL, DATEADD(DAY, -1, GETDATE())
FROM Schedule s JOIN Aircraft a ON s.AircraftId = a.AircraftId
CROSS JOIN (SELECT TOP 200 ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) AS k FROM sys.all_objects) n
WHERE s.DepartureTime > GETDATE() AND s.ScheduleId % 9 = 0 AND s.Status = N'Confirmed'
  AND n.k <= a.EconomySeats - 2 - (s.ScheduleId % 3) - (2 + s.ScheduleId % 7);


SELECT t.UserId, CAST(t.Price / 2 AS INT), N'Flight ' + s.FlightNumber, s.DepartureTime
FROM Ticket t JOIN Schedule s ON t.ScheduleId = s.ScheduleId
WHERE s.DepartureTime < GETDATE() AND t.TicketId % 5 = 0;
GO
SELECT 'Users' AS T, COUNT(*) AS N FROM Users UNION ALL SELECT 'Schedule', COUNT(*) FROM Schedule
UNION ALL SELECT 'Ticket', COUNT(*) FROM Ticket UNION ALL SELECT 'FlightStatus', COUNT(*) FROM FlightStatus
UNION ALL SELECT 'MileagePoints', COUNT(*) FROM MileagePoints;
